function ratio(a, b) {
  return b / a;
}

function cheaperPlan(d) {
  const a = 10 + d;
  const b = 2 * d;
  if (a < b) return "A";
  if (b < a) return "B";
  return "tie";
}

function doublingRatio(T, n) {
  return T(2 * n) / T(n);
}

function growthExponent(T, n) {
  return Math.log2(T(2 * n) / T(n));
}

function firstQuadraticWin(a, b) {
  let n = 1;
  while (!(a * n * n > b * n)) n++;
  return n;
}
